def run(state, revised):
    queue = state["queue"]
    entry = queue[0]
    chapters = []

    for chapter in state["chapters"]:
        updated = dict(chapter)

        if updated["number"] == entry["chapter"]:
            updated["text"] = revised

        chapters.append(updated)

    next_state = dict(state)
    next_state["chapters"] = chapters
    next_state["queue"] = queue[1:]

    return {
        "next": {
            "state": next_state,
            "done": len(queue) <= 1,
            "item": entry["chapter"],
        }
    }
